/* Digi Puzzles — tally engine. One copy serves every tally page in reports/.
   Tally is a 4×4 calcudoku (KenKen-style), built 3 Nov 2026 for Lab on the
   house chrome. The page supplies its puzzle as window.DN_PUZZLE before
   loading this file: {type:"tally", id:"DP·TALLY·0001", band, n:4,
   cages:[{c:[cell…], op:"+"|"-"|"*"|"/"|"=", t}], sol:"16 digits"}.
   Edit here to change every tally; keep element ids and localStorage keys
   stable (dn-track.js and players' saved progress depend on them). */
/* dn-core:start (generated by tools/sync-core.js) */
'use strict';
/* Shared calendar and completed-save rules. Node tools require this file;
   browsers receive identical bundled copies via tools/sync-core.js. Keep the
   existing storage keys, ids and record formats; never redate old results. */
(function(root,factory){
 if(typeof module==='object'&&module.exports)module.exports=factory(root);
 else if(!root.dnCore)root.dnCore=factory(root);
})(typeof globalThis==='object'?globalThis:this,function(root){
 function londonDay(instant){
  const d=instant===undefined?new Date():new Date(instant);
  try{
   const p={};
   new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/London',year:'numeric',month:'2-digit',day:'2-digit'})
    .formatToParts(d).forEach(x=>{p[x.type]=x.value;});
   return p.year+'-'+p.month+'-'+p.day;
  }catch(e){return d.toISOString().slice(0,10);}
 }
 function dayBefore(day){
  const d=new Date(day+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-1);return d.toISOString().slice(0,10);
 }
 const object=x=>!!x&&typeof x==='object'&&!Array.isArray(x);
 // Track actual game-save failures only. No storage probes, timers or global
 // Storage patching. Pending data lives in this tab until a real write succeeds.
 const scopes=new WeakMap(),listeners=new Set();
 function scope(storage){
  const owner=storage||root;
  if(!scopes.has(owner))scopes.set(owner,{issues:new Map(),done:new Map()});
  return scopes.get(owner);
 }
 function changed(storage){if(!storage)listeners.forEach(fn=>{try{fn();}catch(e){}});}
 function failed(key,retry,storage){const issues=scope(storage).issues,was=issues.has(key);issues.set(key,retry);if(!was)changed(storage);}
 function saved(key,storage){if(scope(storage).issues.delete(key))changed(storage);}
 function saveIssues(){return scope().issues.size;}
 function onSaveChange(fn){listeners.add(fn);return ()=>listeners.delete(fn);}
 async function retrySaves(){
  for(const retry of Array.from(scope().issues.values())){try{await retry();}catch(e){}}
  return saveIssues()===0;
 }
 function read(key,storage){
  try{const s=JSON.parse((storage||root.localStorage).getItem(key)||'null');return object(s)&&s.v===1?s:null;}
  catch(e){return null;}
 }
 function getDone(key,id,storage){const s=read(key,storage),pending=scope(storage).done.get(key);return s&&object(s.done)&&s.done[id]||pending&&pending[id]||null;}
 function putDone(key,id,rec,storage){
  const state=scope(storage),pending=state.done.get(key)||{};
  const s=read(key,storage)||{v:1};if(!object(s.done))s.done={};
  if(s.done[id]&&!Object.keys(pending).length)return s.done[id];
  const first=s.done[id]||pending[id]||Object.assign({},rec,{d:londonDay()});
  pending[id]=first;state.done.set(key,pending);
  if(Object.keys(pending).every(k=>s.done[k])){state.done.delete(key);saved(key,storage);return first;}
  s.done=Object.assign({},pending,s.done);
  try{
   (storage||root.localStorage).setItem(key,JSON.stringify(s));
   state.done.delete(key);saved(key,storage);return first;
  }catch(e){failed(key,()=>putDone(key,id,first,storage),storage);return null;}
 }
 function mergeStreak(a,b){
  a=object(a)?a:{};b=object(b)?b:{};
  const valid=s=>/^\d{4}-\d{2}-\d{2}$/.test(s.last||'');
  const newer=valid(b)&&(!valid(a)||b.last>a.last)?b:a,older=newer===a?b:a;
  let n=Number(newer.n)||0;
  if(valid(newer)&&valid(older)){
   if(newer.last===older.last)n=Math.max(n,Number(older.n)||0);
   else if(dayBefore(newer.last)===older.last)n=Math.max(n,(Number(older.n)||0)+1);
  }
  return Object.assign({},older,newer,{n,best:Math.max(n,Number(a.best)||0,Number(b.best)||0)});
 }
 function mergeProgress(current,stored,activeId){
  if(!stored)return current;
  const merged=Object.assign({},stored,current);
  // The stored result was committed first. Replaying or an older tab cannot
  // replace it; new ids from either tab survive. Other save fields stay intact.
  merged.done=Object.assign({},object(current.done)?current.done:{},object(stored.done)?stored.done:{});
  if(object(current.days)||object(stored.days)){
   merged.days=Object.assign({},object(current.days)?current.days:{},object(stored.days)?stored.days:{});
   const local=object(current.days)&&current.days[activeId],remote=object(stored.days)&&stored.days[activeId];
   if(local&&(!remote||remote.state!=='done'))merged.days[activeId]=local;
  }
  if(current.streak||stored.streak)merged.streak=mergeStreak(current.streak,stored.streak);
  if('best' in current||'best' in stored)merged.best=Math.max(Number(current.best)||0,Number(stored.best)||0);
  return merged;
 }
 function same(a,b){
  if(a===b)return true;
  if(!a||!b||typeof a!=='object'||typeof b!=='object'||Array.isArray(a)!==Array.isArray(b))return false;
  const keys=Object.keys(a);
  return keys.length===Object.keys(b).length&&keys.every(k=>Object.prototype.hasOwnProperty.call(b,k)&&same(a[k],b[k]));
 }
 function progressOnly(s){
  s=s||{};
  const days=Object.fromEntries(Object.entries(s.days||{}).filter(([,d])=>d&&d.state!=='ready'));
  return {done:s.done||{},days,cur:s.cur||null,streak:s.streak&&s.streak.last?s.streak:null,best:s.best||0};
 }
 function saveProgress(key,current,activeId,storage,report=true){
  // Merge even if writing fails, so the current tab retains the results it read.
  let pending=report;
  try{
   const stored=read(key,storage);
   Object.assign(current,mergeProgress(current,stored,activeId));
   if(stored&&same(current,stored)){saved(key,storage);return current;}
   // A later housekeeping/settings write must not warn about game data that
   // is already durable. Compare data, not property order or storage capacity.
   pending=report&&!same(progressOnly(current),progressOnly(stored));
   (storage||root.localStorage).setItem(key,JSON.stringify(current));saved(key,storage);
  }catch(e){if(pending||scope(storage).issues.has(key))failed(key,()=>saveProgress(key,current,activeId,storage,true),storage);}
  return current;
 }
 async function saveStreak(key,value,external){
  try{external=external===undefined?root.storage:external;if(external){await external.set(key,JSON.stringify(value));saved(key);return true;}}catch(e){}
  try{root.localStorage.setItem(key,JSON.stringify(value));saved(key);return true;}
  catch(e){failed(key,()=>saveStreak(key,value,external));return false;}
 }
 return {londonDay,dayBefore,getDone,putDone,mergeProgress,saveProgress,saveStreak,saveIssues,onSaveChange,retrySaves};
});
/* dn-core:end */

/* the shared finish sheet (engines/finish.js): calls made before it loads are queued */
window.dnFinish=window.dnFinish||{q:[],show(c){this.q.push(c)},hide(){}};
document.write('<link rel="stylesheet" href="../engines/finish.css"><link rel="stylesheet" href="../engines/house.css"><script src="../engines/finish.js"><\/script><script src="../engines/house.js"><\/script>');
(function(){
"use strict";
const PUZZLE=window.DN_PUZZLE;
const N=PUZZLE.n||4, CELLS=N*N;
const OPS={'+':'+','-':'−','*':'×','/':'÷','=':''};
const $=id=>document.getElementById(id);
const gridEl=$("grid"),keysEl=$("keys"),msgEl=$("msg"),timerEl=$("timer");
const meta=n=>{const m=document.querySelector('meta[name="'+n+'"]');return m?m.content:"";};
const LAB=!!meta("dn:badge");   // in Lab the share carries the page's own address (no short link yet)

/* ---------- rules ---------- */
function label(cg){return cg.op==='='?String(cg.t):cg.t+OPS[cg.op];}
/* the clue as two parts, number then sign, so the sign can be drawn larger and in colour (Alec, 3 Nov 2026: the small signs read alike) */
function clueNode(cg){const s=document.createElement("span");s.className="clue";s.setAttribute("aria-label",label(cg));
  const n=document.createElement("b");n.textContent=cg.t;s.appendChild(n);
  if(cg.op!=='='){const o=document.createElement("i");o.className="op op-"+({'+':'add','-':'sub','*':'mul','/':'div'}[cg.op]);o.textContent=OPS[cg.op];s.appendChild(o);}
  return s;}
function satisfies(op,t,v){
  if(op==='=')return v.length===1&&v[0]===t;
  if(op==='+')return v.reduce((a,b)=>a+b,0)===t;
  if(op==='*')return v.reduce((a,b)=>a*b,1)===t;
  if(op==='-')return v.length===2&&Math.abs(v[0]-v[1])===t;
  if(op==='/'){if(v.length!==2)return false;const hi=Math.max(v[0],v[1]),lo=Math.min(v[0],v[1]);return hi%lo===0&&hi/lo===t;}
  return false;
}
/* ship gate at load: the page refuses to render a board that breaks the rules */
function gate(p){
  const errs=[],seen=new Array(CELLS).fill(false);
  if(!p||!Array.isArray(p.cages)||typeof p.sol!=="string"||p.sol.length!==CELLS)return["malformed puzzle"];
  for(const cg of p.cages){
    if(!cg.c.length||cg.c.length>4)errs.push("cage size");
    for(const i of cg.c){if(seen[i])errs.push("cell in two cages");seen[i]=true;}
    if((cg.op==='-'||cg.op==='/')&&cg.c.length!==2)errs.push(cg.op+" on "+cg.c.length+" cells");
    if(!satisfies(cg.op,cg.t,cg.c.map(i=>+p.sol[i])))errs.push("clue "+label(cg)+" does not match");
  }
  if(seen.some(s=>!s))errs.push("a cell belongs to no cage");
  for(let r=0;r<N;r++){const a=new Set(),b=new Set();for(let c=0;c<N;c++){a.add(p.sol[r*N+c]);b.add(p.sol[c*N+r]);}if(a.size!==N||b.size!==N)errs.push("solution is not a Latin square");}
  return errs;
}
const GATE=gate(PUZZLE);
if(GATE.length){msgEl.textContent="This board failed its check and can't be played: "+GATE.join("; ");throw new Error("tally gate: "+GATE.join("; "));}

/* ---------- streak (digi-tally-streak, London days) ---------- */
const STREAK_KEY="digi-tally-streak", DONE_KEY="digi-tally-v1";
function today(){return window.dnCore.londonDay();}
function dayBefore(s){return window.dnCore.dayBefore(s);}
function streakGet(){try{const s=JSON.parse(localStorage.getItem(STREAK_KEY)||"null");return s&&typeof s==="object"?s:null;}catch(e){return null;}}
function streakLive(){const s=streakGet(),t=today();return s&&(s.last===t||s.last===dayBefore(t))?(s.streak||0):0;}
function streakBump(){
  const s=streakGet()||{last:null,streak:0,best:0,dates:[]},t=today();
  if(!(s.dates||[]).includes(t)){
    s.streak=s.last===dayBefore(t)?(s.streak||0)+1:1; s.best=Math.max(s.best||0,s.streak);
    s.last=t; s.tz="L"; s.dates=[...new Set([...(s.dates||[]),t])].slice(-90);
    window.dnCore.saveStreak(STREAK_KEY,s,null);
  }
  return s.streak||0;
}

/* ---------- state ---------- */
const state={g:new Array(CELLS).fill(0),notes:new Array(CELLS).fill(0),sel:-1,notesMode:false,undo:[],secs:0,t0:null,timer:null,solved:false,streak:streakLive(),resumed:false};
$("streakn").textContent=state.streak;
/* player-facing number: "Tally 10", not the padded id (ids, filenames and keys keep the padding) */
$("pid").textContent="Tally "+parseInt(String(PUZZLE.id).split("·").pop(),10);
$("modalsub").textContent=PUZZLE.id+" · "+String(PUZZLE.band||"").toUpperCase();
const cageOf=new Array(CELLS);PUZZLE.cages.forEach((cg,k)=>cg.c.forEach(i=>{cageOf[i]=k;}));
const cells=[];
function fmt(s){s=Math.max(0,Math.round(s));return Math.floor(s/60)+":"+String(s%60).padStart(2,"0");}
function setMsg(t){msgEl.textContent=t;}

/* ---------- clock: waits at zero until Play (house) or the first tap, pauses while the page is away ---------- */
function startTimer(){
  if(state.solved||state.timer)return;
  state.t0=Date.now();timerEl.classList.remove("waiting");
  state.timer=setInterval(()=>{timerEl.textContent=fmt(state.secs+(Date.now()-state.t0)/1000);},250);
}
function stopTimer(){if(state.timer){clearInterval(state.timer);state.timer=null;}if(state.t0){state.secs+=(Date.now()-state.t0)/1000;state.t0=null;}}
window.addEventListener("dn:play",()=>{if(!state.solved)startTimer();});
document.addEventListener("visibilitychange",()=>{
  if(state.solved)return;
  if(document.hidden){const was=!!state.timer;stopTimer();state.away=was;timerEl.classList.add("waiting");saveCur();}
  else if(state.away){state.away=false;startTimer();}
});
window.addEventListener("pagehide",()=>{if(!state.solved){stopTimer();saveCur();}});
timerEl.classList.add("waiting");

/* ---------- an unfinished board is kept in digi-tally-v1.cur (beside done, which only putDone writes) ---------- */
function readSave(){try{const s=JSON.parse(localStorage.getItem(DONE_KEY)||"null");return s&&typeof s==="object"?s:{v:1};}catch(e){return {v:1};}}
function saveCur(){
  if(state.solved||window.dnCore.getDone(DONE_KEY,PUZZLE.id))return;
  try{const s=readSave();
    if(state.g.some(Boolean)||state.notes.some(Boolean))s.cur={id:PUZZLE.id,g:state.g,notes:state.notes,s:Math.round(state.secs+(state.t0?(Date.now()-state.t0)/1000:0)),at:Date.now()};
    else if(s.cur&&s.cur.id===PUZZLE.id)delete s.cur;
    else return;
    localStorage.setItem(DONE_KEY,JSON.stringify(s));
  }catch(e){}
}
function clearCur(){try{const s=readSave();if(s.cur&&s.cur.id===PUZZLE.id){delete s.cur;localStorage.setItem(DONE_KEY,JSON.stringify(s));}}catch(e){}}
function restoreCur(){
  const s=readSave(),c=s.cur;
  if(!c||c.id!==PUZZLE.id||!Array.isArray(c.g)||c.g.length!==CELLS)return;
  state.g=c.g.map(v=>+v||0);state.notes=Array.isArray(c.notes)&&c.notes.length===CELLS?c.notes.map(v=>+v||0):new Array(CELLS).fill(0);
  state.secs=+c.s||0;state.resumed=true;timerEl.textContent=fmt(state.secs);
}

/* ---------- the board ---------- */
function build(){
  gridEl.innerHTML="";cells.length=0;
  for(let i=0;i<CELLS;i++){
    const r=Math.floor(i/N),c=i%N,k=cageOf[i],b=document.createElement("button");
    b.type="button";b.className="cell";b.setAttribute("role","gridcell");b.dataset.i=i;b.dataset.cage=k;
    if(r===0||cageOf[i-N]!==k)b.classList.add("bt");if(r===N-1||cageOf[i+N]!==k)b.classList.add("bb");
    if(c===0||cageOf[i-1]!==k)b.classList.add("bl");if(c===N-1||cageOf[i+1]!==k)b.classList.add("br");
    if(PUZZLE.cages[k].c[0]===i){b.appendChild(clueNode(PUZZLE.cages[k]));}
    const v=document.createElement("span");v.className="val";b.appendChild(v);
    const nt=document.createElement("span");nt.className="notes";for(let d=1;d<=N;d++){const e=document.createElement("span");e.textContent=d;nt.appendChild(e);}b.appendChild(nt);
    b.addEventListener("pointerdown",e=>{e.preventDefault();select(i);});
    gridEl.appendChild(b);cells.push(b);
  }
  keysEl.innerHTML="";
  for(let d=1;d<=N;d++){const k=document.createElement("button");k.type="button";k.textContent=d;k.dataset.d=d;k.setAttribute("aria-label","Enter "+d);k.addEventListener("click",()=>enter(d));keysEl.appendChild(k);}
}
function select(i){if(state.solved)return;state.sel=i;startTimer();paint();}
function paint(){
  const g=state.g,rowDup=new Set(),colDup=new Set();
  for(let r=0;r<N;r++){const seen={},seenC={};for(let c=0;c<N;c++){
    const i=r*N+c,v=g[i];if(v){if(seen[v]!=null){rowDup.add(i);rowDup.add(seen[v]);}seen[v]=i;}
    const j=c*N+r,w=g[j];if(w){if(seenC[w]!=null){colDup.add(j);colDup.add(seenC[w]);}seenC[w]=j;}}}
  const sel=state.sel,selCage=sel>=0?cells[sel].dataset.cage:null,selVal=sel>=0?g[sel]:0;
  for(let i=0;i<CELLS;i++){
    const b=cells[i],v=g[i];
    b.querySelector(".val").textContent=v||"";
    b.classList.toggle("has",!!v);
    b.classList.toggle("bad",rowDup.has(i)||colDup.has(i));
    const ns=b.querySelectorAll(".notes span");for(let d=1;d<=N;d++)ns[d-1].classList.toggle("on",!!(state.notes[i]&(1<<d)));
    b.classList.toggle("sel",i===sel);
    b.classList.toggle("cage",i!==sel&&selCage!=null&&b.dataset.cage===selCage);
    b.classList.toggle("peer",i!==sel&&selCage!=null&&b.dataset.cage!==selCage&&(Math.floor(i/N)===Math.floor(sel/N)||i%N===sel%N));
    b.classList.toggle("same",i!==sel&&!!selVal&&v===selVal);
    b.setAttribute("aria-label","Row "+(Math.floor(i/N)+1)+", column "+(i%N+1)+(v?", "+v:", empty")+(b.querySelector(".clue")?", cage "+b.querySelector(".clue").textContent:""));
  }
  PUZZLE.cages.forEach(cg=>{const el=cells[cg.c[0]].querySelector(".clue");if(!el)return;const vals=cg.c.map(i=>g[i]),full=vals.every(Boolean);el.classList.toggle("ok",full&&satisfies(cg.op,cg.t,vals));el.classList.toggle("bad",full&&!satisfies(cg.op,cg.t,vals));});
  $("undoBtn").disabled=!state.undo.length;
}
function snapshot(){state.undo.push({g:state.g.slice(),notes:state.notes.slice()});if(state.undo.length>200)state.undo.shift();}
function enter(d){
  if(state.solved)return;
  if(state.sel<0){setMsg("Tap a square first.");return;}
  startTimer();snapshot();const i=state.sel;
  if(state.notesMode){if(state.g[i])state.g[i]=0;state.notes[i]^=(1<<d);}
  else{state.g[i]=state.g[i]===d?0:d;state.notes[i]=0;
    if(state.g[i]){const r=Math.floor(i/N),c=i%N;for(let j=0;j<CELLS;j++)if(j!==i&&(Math.floor(j/N)===r||j%N===c))state.notes[j]&=~(1<<d);}}
  setMsg("");paint();saveCur();checkWin();
}
function erase(){if(state.solved||state.sel<0)return;snapshot();state.g[state.sel]=0;state.notes[state.sel]=0;paint();saveCur();}
function doUndo(){if(state.solved||!state.undo.length)return;const u=state.undo.pop();state.g=u.g;state.notes=u.notes;paint();saveCur();}
$("notesBtn").addEventListener("click",()=>{state.notesMode=!state.notesMode;$("notesBtn").setAttribute("aria-pressed",String(state.notesMode));setMsg(state.notesMode?"Notes on: numbers go in small.":"");});
$("eraseBtn").addEventListener("click",erase);
$("undoBtn").addEventListener("click",doUndo);
document.addEventListener("keydown",e=>{
  if(state.solved||e.ctrlKey||e.metaKey||e.altKey)return;
  if(document.documentElement.classList.contains("dn-starting"))return;
  const d=parseInt(e.key,10);
  if(d>=1&&d<=N&&e.key.length===1){enter(d);e.preventDefault();}
  else if(e.key==="Backspace"||e.key==="Delete"||e.key==="0"){erase();e.preventDefault();}
  else if(e.key==="n"||e.key==="N")$("notesBtn").click();
  else if(/^Arrow/.test(e.key)){let s=state.sel<0?0:state.sel;const r=Math.floor(s/N),c=s%N;
    if(e.key==="ArrowUp"&&r>0)s-=N;if(e.key==="ArrowDown"&&r<N-1)s+=N;if(e.key==="ArrowLeft"&&c>0)s--;if(e.key==="ArrowRight"&&c<N-1)s++;
    state.sel=s;paint();e.preventDefault();}
});

/* ---------- finish ---------- */
function solvedNow(){
  const g=state.g;if(g.some(v=>!v))return false;
  for(let r=0;r<N;r++){const a=new Set(),b=new Set();for(let c=0;c<N;c++){a.add(g[r*N+c]);b.add(g[c*N+r]);}if(a.size!==N||b.size!==N)return false;}
  return PUZZLE.cages.every(cg=>satisfies(cg.op,cg.t,cg.c.map(i=>g[i])));
}
function checkWin(){if(!state.solved&&solvedNow())finish();}
function dnNum(id){const n=parseInt(String(id).split("·").pop(),10);return isNaN(n)?"":"#"+n;}
function dnStreak(n){n=parseInt(String(n||"").replace(/\D/g,""),10)||0;return n>=2?" · 🔥"+n:"";}
function shareText(){return "🧮 Tally "+dnNum(PUZZLE.id)+" — "+timerEl.textContent.trim()+dnStreak(String(state.streak));}
function finish(){
  stopTimer();state.solved=true;state.sel=-1;paint();document.body.classList.add("win");
  const secs=Math.round(state.secs),t=fmt(secs);
  timerEl.textContent=t;
  state.streak=streakBump();$("streakn").textContent=state.streak;
  $("statTime").textContent=t;$("statStreak").textContent=state.streak;
  window.dnCore.putDone(DONE_KEY,PUZZLE.id,{t,s:secs});clearCur();
  setMsg("Solved in "+t+".");
  finishSheet(true);
  try{document.documentElement.setAttribute("data-dn-done","");}catch(e){}
  $("modal").classList.add("on");   // the tracker reads the result box once it opens
}
function recapNode(){
  const wrap=document.createElement("div");wrap.className="fin-tally";
  for(let i=0;i<CELLS;i++){
    const r=Math.floor(i/N),c=i%N,k=cageOf[i],e=document.createElement("i");
    if(r===0||cageOf[i-N]!==k)e.classList.add("bt");if(r===N-1||cageOf[i+N]!==k)e.classList.add("bb");
    if(c===0||cageOf[i-1]!==k)e.classList.add("bl");if(c===N-1||cageOf[i+1]!==k)e.classList.add("br");
    if(PUZZLE.cages[k].c[0]===i){const s=document.createElement("small");s.textContent=label(PUZZLE.cages[k]);s.setAttribute("aria-hidden","true");e.appendChild(s);}
    e.appendChild(document.createTextNode(PUZZLE.sol[i]));wrap.appendChild(e);
  }
  return wrap;
}
function finishSheet(fresh){
  const h2=document.querySelector("#modal h2");if(h2){h2.id="winTitle";h2.textContent="Solved";}
  let played=0;try{const s=readSave();played=s.done?Object.keys(s.done).length:0;}catch(e){}
  const st=streakGet()||{};
  const note=fresh?(state.resumed?"Picked up where you left off.":""):"";
  const share={text:shareText};
  if(LAB)share.url="dailynoodle.co.uk"+location.pathname;   // Lab: no short link yet, share the page itself
  window.dnFinish.show({type:"tally",id:PUZZLE.id,n:parseInt(String(PUZZLE.id).split("·").pop(),10),date:meta("dn:date"),
    box:"modal",title:"winTitle",hero:"statTime",note,share,lab:LAB,
    stats:[{id:"statStreak",label:"day streak"},{value:Math.max(st.best||0,state.streak||0),label:"best streak"},{value:played,label:"boards played"}],
    recap:{title:"The board",sub:"Every row and column 1 to "+N+"; each cage makes its clue.",node:recapNode()}});
}
/* a finished puzzle reopens finished: the solution shown, the sheet without the tracker's "on" */
function restoreDone(){
  const rec=window.dnCore.getDone(DONE_KEY,PUZZLE.id);if(!rec)return false;
  const t=(/^\d{1,4}:\d{2}$/.test(String(rec.t))?String(rec.t):null)||"0:00";
  state.g=PUZZLE.sol.split("").map(Number);state.notes.fill(0);state.solved=true;state.sel=-1;
  stopTimer();timerEl.textContent=t;timerEl.classList.remove("waiting");$("statTime").textContent=t;$("statStreak").textContent=state.streak;
  paint();document.body.classList.add("win");setMsg("Solved in "+t+".");
  try{document.documentElement.setAttribute("data-dn-done","");}catch(e){}
  finishSheet(false);
  return true;
}
$("closeBtn").addEventListener("click",()=>{$("modal").classList.remove("on");window.dnFinish.hide();});
$("shareBtn").addEventListener("click",()=>{const text=shareText();if(navigator.share)navigator.share({text}).catch(()=>{});else setMsg(text);});

build();
if(!restoreDone()){restoreCur();paint();if(state.resumed)setMsg("Carrying on where you left off.");}
})();
